+
+  NVTE_CHECK_CUDA(cudaGraphExecDestroy(exec));
+  NVTE_CHECK_CUDA(cudaGraphDestroy(graph));
+  NVTE_CHECK_CUDA(cudaStreamDestroy(stream));
+}
