+    // per-expert amax base and a local row offset so amax[row_idx] indexes the
+    // expert-local row.
+    rowwise_scaling<ScaleType, USE_STOCHASTIC_ROUNDING, USE_FAST_MATH, ROW_SCALED_NVFP4>(
